import{_ as l,a0 as p,w as o,s as r,I as t,x as e,a1 as a,A as n,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用 Git 工作樹對你的代碼進行自由實驗 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Git 工作樹對你的代碼進行自由實驗 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Git 工作樹對你的代碼進行自由實驗 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Git 工作樹對你的代碼進行自由實驗 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210406 Experiment on your code freely with Git worktree","title":"使用 Git 工作樹對你的代碼進行自由實驗","tag":"202104","desc":""},"relativePath":"202104/20210406 Experiment on your code freely with Git worktree.md","filePath":"[post].md"}'),h={name:"202104/20210406 Experiment on your code freely with Git worktree.md"};function g(k,s,c,u,b,f){const i=p("Link");return o(),r("div",null,[s[22]||(s[22]=t("h1",{id:"使用-git-工作樹對你的代碼進行自由實驗",tabindex:"-1"},[e("使用 Git 工作樹對你的代碼進行自由實驗 "),t("a",{class:"header-anchor",href:"#使用-git-工作樹對你的代碼進行自由實驗","aria-label":"Permalink to “使用 Git 工作樹對你的代碼進行自由實驗”"},"​")],-1)),s[23]||(s[23]=t("blockquote",null,[t("p",null,"獲得自由嘗試的權利，同時在你的實驗出錯時可以安全地擁有一個新的、鏈接的克隆存儲庫。")],-1)),s[24]||(s[24]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202104/16/085512x3auafu5uaymk52u.jpg",alt:""})],-1)),s[25]||(s[25]=t("p",null,"Git 的設計部分是為了進行實驗。如果你知道你的工作會被安全地跟蹤，並且在出現嚴重錯誤時有安全狀態存在，你就不會害怕嘗試新的想法。不過，創新的部分代價是，你很可能會在這個過程中弄得一團糟。文件會被重新命名、移動、刪除、更改、切割成碎片；新的文件被引入；你不打算跟蹤的臨時文件會在你的工作目錄中佔據一席之地等等。",-1)),t("p",null,[s[1]||(s[1]=e("簡而言之，你的工作空間變成了紙牌屋，在“快好了！”和“哦，不，我做了什麼？”之間岌岌可危地平衡着。那麼，當你需要把倉庫恢復到下午的一個已知狀態，以便完成一些真正的工作時，該怎麼辦？我立刻想到了 ",-1)),s[2]||(s[2]=t("code",null,"git branch",-1)),s[3]||(s[3]=e(" 和 ",-1)),a(i,{href:"https://linux.cn/article-13293-1.html"},{default:n(()=>[...s[0]||(s[0]=[e("git stash",-1)])]),_:1}),s[4]||(s[4]=e(" 這兩個經典命令，但這兩個命令都不是用來處理未被跟蹤的文件的，而且文件路徑的改變和其他重大的轉變也會讓人困惑，它們只能把工作暫存（",-1)),s[5]||(s[5]=t("code",null,"stash",-1)),s[6]||(s[6]=e("）起來以備後用。解決這個需求的答案是 Git 工作樹。",-1))]),s[26]||(s[26]=d(`<h3 id="什麼是-git-工作樹" tabindex="-1">什麼是 Git 工作樹 <a class="header-anchor" href="#什麼是-git-工作樹" aria-label="Permalink to “什麼是 Git 工作樹”">​</a></h3><p>Git <ruby>工作樹<rt>worktree</rt></ruby>是 Git 倉庫的一個鏈接副本，允許你同時簽出多個分支。工作樹與主工作副本的路徑是分開的，它可以處於不同的狀態和不同的分支上。在 Git 中新建工作樹的好處是，你可以在不干擾當前工作環境的情況下，做出與當前任務無關的修改、提交修改，然後在以後合併。</p><p>直接從 <code>git-worktree</code> 手冊中找到了一個典型的例子：當你正在為一個項目做一個令人興奮的新功能時，你的項目經理告訴你有一個緊急的修復工作。問題是你的工作倉庫（你的“工作樹”）處於混亂狀態，因為你正在開發一個重要的新功能。你不想在當前的衝刺中“偷偷地”進行修復，而且你也不願意把變更暫存起來，為修復創建一個新的分支。相反，你決定創建一個新的工作樹，這樣你就可以在那裏進行修復：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git branch | tee</span></span>
<span class="line"><span>* dev</span></span>
<span class="line"><span>trunk</span></span>
<span class="line"><span>$ git worktree add -b hotfix ~/code/hotfix trunk</span></span>
<span class="line"><span>Preparing ../hotfix (identifier hotfix)</span></span>
<span class="line"><span>HEAD is now at 62a2daf commit</span></span></code></pre></div><p>在你的 <code>code</code> 目錄中，你現在有一個新的目錄叫做 <code>hotfix</code>，它是一個與你的主項目倉庫相連的 Git 工作樹，它的 <code>HEAD</code> 停在叫做 <code>trunk</code> 的分支上。現在你可以把這個工作樹當作你的主工作區來對待。你可以把目錄切換到它裏面，進行緊急修復、提交、並最終刪除這個工作樹：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/code/hotfix</span></span>
<span class="line"><span>$ sed -i &#39;s/teh/the/&#39; hello.txt</span></span>
<span class="line"><span>$ git commit --all --message &#39;urgent hot fix&#39;</span></span></code></pre></div><p>一旦你完成了你的緊急工作，你就可以回到你之前的任務。你可以控制你的熱修復何時被集成到主項目中。例如，你可以直接將變更從其工作樹推送到項目的遠程存儲庫中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git push origin HEAD</span></span>
<span class="line"><span>$ cd ~/code/myproject</span></span></code></pre></div><p>或者你可以將工作樹存檔為 TAR 或 ZIP 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/code/myproject</span></span>
<span class="line"><span>$ git archive --format tar --output hotfix.tar master</span></span></code></pre></div><p>或者你可以從單獨的工作樹中獲取本地的變化：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git worktree list</span></span>
<span class="line"><span>/home/seth/code/myproject  15fca84 [dev]</span></span>
<span class="line"><span>/home/seth/code/hotfix     09e585d [master]</span></span></code></pre></div><p>從那裏，你可以使用任何最適合你和你的團隊的策略合併你的變化。</p><h3 id="列出活動工作樹" tabindex="-1">列出活動工作樹 <a class="header-anchor" href="#列出活動工作樹" aria-label="Permalink to “列出活動工作樹”">​</a></h3><p>你可以使用 <code>git worktree list</code> 命令獲得工作樹的列表，並查看每個工作樹簽出的分支：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git worktree list</span></span>
<span class="line"><span>/home/seth/code/myproject  15fca84 [dev]</span></span>
<span class="line"><span>/home/seth/code/hotfix     09e585d [master]</span></span></code></pre></div><p>你可以在任何一個工作樹中使用這個功能。工作樹始終是連接的（除非你手動移動它們，破壞 Git 定位工作樹的能力，從而切斷連接）。</p><h3 id="移動工作樹" tabindex="-1">移動工作樹 <a class="header-anchor" href="#移動工作樹" aria-label="Permalink to “移動工作樹”">​</a></h3><p>Git 會跟蹤項目 <code>.git</code> 目錄下工作樹的位置和狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat ~/code/myproject/.git/worktrees/hotfix/gitdir</span></span>
<span class="line"><span>/home/seth/code/hotfix/.git</span></span></code></pre></div><p>如果你需要重定位一個工作樹，必須使用 <code>git worktree move</code>；否則，當 Git 試圖更新工作樹的狀態時，就會失敗：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/Temp</span></span>
<span class="line"><span>$ git worktree move hotfix ~/Temp</span></span>
<span class="line"><span>$ git worktree list</span></span>
<span class="line"><span>/home/seth/code/myproject  15fca84 [dev]</span></span>
<span class="line"><span>/home/seth/Temp/hotfix     09e585d [master]</span></span></code></pre></div><h3 id="移除工作樹" tabindex="-1">移除工作樹 <a class="header-anchor" href="#移除工作樹" aria-label="Permalink to “移除工作樹”">​</a></h3><p>當你完成你的工作時，你可以用 <code>remove</code> 子命令刪除它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git worktree remove hotfix</span></span>
<span class="line"><span>$ git worktree list</span></span>
<span class="line"><span>/home/seth/code/myproject  15fca84 [dev]</span></span></code></pre></div><p>為了確保你的 <code>.git</code> 目錄是乾淨的，在刪除工作樹後使用 <code>prune</code> 子命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git worktree remove prune</span></span></code></pre></div><h3 id="何時使用工作樹" tabindex="-1">何時使用工作樹 <a class="header-anchor" href="#何時使用工作樹" aria-label="Permalink to “何時使用工作樹”">​</a></h3><p>與許多選項一樣，無論是標籤還是書籤還是自動備份，都要靠你來跟蹤你產生的數據，否則可能會變得不堪重負。不要經常使用工作樹，要不你最終會有 20 份存儲庫的副本，每份副本的狀態都略有不同。我發現最好是創建一個工作樹，做需要它的任務，提交工作，然後刪除樹。保持簡單和專注。</p><p>重要的是，工作樹為你管理 Git 存儲庫的方式提供了更好的靈活性。在需要的時候使用它們，再也不用為了檢查另一個分支上的內容而爭先恐後地保存工作狀態了。</p><hr>`,31)),t("p",null,[s[8]||(s[8]=e("via: ",-1)),a(i,{href:"https://opensource.com/article/21/4/git-worktree"},{default:n(()=>[...s[7]||(s[7]=[e("https://opensource.com/article/21/4/git-worktree",-1)])]),_:1})]),t("p",null,[s[13]||(s[13]=e("作者：",-1)),a(i,{href:"https://opensource.com/users/seth"},{default:n(()=>[...s[9]||(s[9]=[e("Seth Kenlon",-1)])]),_:1}),s[14]||(s[14]=e(" 選題：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[10]||(s[10]=[e("lujun9972",-1)])]),_:1}),s[15]||(s[15]=e(" 譯者：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[11]||(s[11]=[e("wxy",-1)])]),_:1}),s[16]||(s[16]=e(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[12]||(s[12]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[19]||(s[19]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[17]||(s[17]=[e("LCTT",-1)])]),_:1}),s[20]||(s[20]=e(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...s[18]||(s[18]=[e("Linux中國",-1)])]),_:1}),s[21]||(s[21]=e(" 榮譽推出",-1))])])}const C=l(h,[["render",g]]);export{y as __pageData,C as default};
